 const addWeight=(value:number)=>{if(!session||!supabase)return notify('Vaznni saqlash uchun kiring.');const day=todayInTashkent();supabase.from('weight_logs').upsert({user_id:session.user.id,logged_on:day,weight_kg:value},{onConflict:'user_id,logged_on'}).then(({error})=>{if(error)return notify('Vazn saqlanmadi. Qayta urinib ko‘ring.');setWeights(current=>current.length?current.slice(0,-1).concat(value):[value]);notify('Vazn qayd etildi')})};
