 {!installed&&<button className="install-call" onClick={async()=>{if(installEvt){installEvt.prompt();await installEvt.userChoice;setInstallEvt(null)}else notify(/iphone|ipad|ipod/i.test(navigator.userAgent)?'Safari’da Share → Add to Home Screen ni tanlang.':'Brauzer menyusidan “Install app” yoki “Add to Home Screen” ni tanlang.')}}><Activity size={17}/><span><b>ArniyGym’ni o‘rnating</b><small>Telefoningizda ilova kabi foydalaning</small></span><ArrowRight size={16}/></button>}
 {showAuth&&<AuthModal onClose={()=>setShowAuth(false)} notify={notify}/>}{showAdminAuth&&<AdminAuthModal onClose={()=>setShowAdminAuth(false)} onSuccess={()=>{setShowAdminAuth(false);goto('admin')}} notify={notify}/>}{showProgress&&<ProgressModal water={water.count} onWater={alterWater} weights={weights} onWeight={addWeight} session={session} onAuth={()=>{setShowProgress(false);setShowAuth(true)}} onClose={()=>setShowProgress(false)} notify={notify}/>}
