 const [videoPlanId,setVideoPlanId]=useState(''),[videoTitle,setVideoTitle]=useState(''),[videoTitleRu,setVideoTitleRu]=useState(''),[videoDescription,setVideoDescription]=useState(''),[videoDescriptionRu,setVideoDescriptionRu]=useState(''),[videoFile,setVideoFile]=useState<File|null>(null),[videoBusy,setVideoBusy]=useState(false),[videoProgress,setVideoProgress]=useState(0),[videoRows,setVideoRows]=useState<any[]>([]);
 const reset=()=>{setEditingId('');setTitle('');setTitleRu('');setBody(emptyContent())};
 useEffect(()=>{const options=diets.filter(x=>x.goal===goal);if(!options.some(x=>x.id===videoPlanId))setVideoPlanId(options[0]?.id||'')},[diets,goal]);
 useEffect(()=>{let alive=true;setVideoRows([]);if(!videoPlanId||!supabase)return()=>{alive=false};supabase.from('diet_plan_media').select('id,diet_plan_id,stream_video_id,title,title_ru,description,description_ru,created_at').eq('diet_plan_id',videoPlanId).order('created_at',{ascending:false}).then(({data,error})=>{if(!alive)return;if(error)notify('So‘rov muvaffaqiyatsiz. Qayta urinib ko‘ring.');else setVideoRows(data||[])});return()=>{alive=false}},[videoPlanId]);
